class MainHomeWidget extends StatefulWidget {
  const MainHomeWidget({
    super.key,
    this.tabIndex,
    this.scrollToCourseId,
  });

  final int? tabIndex;
  final String? scrollToCourseId;

  static String routeName = 'mainHome';
  static String routePath = 'mainHome';

  @override
  State<MainHomeWidget> createState() => _MainHomeWidgetState();
}

class _MainHomeWidgetState extends State<MainHomeWidget>
    with TickerProviderStateMixin {
  late MainHomeModel _model;

  final scaffoldKey = GlobalKey<ScaffoldState>();
  late StreamSubscription<bool> _keyboardVisibilitySubscription;
  bool _isKeyboardVisible = false;

  @override
  void initState() {
    super.initState();
    _model = createModel(context, () => MainHomeModel());

    logFirebaseEvent('screen_view', parameters: {'screen_name': 'mainHome'});
    // On page load action.
    SchedulerBinding.instance.addPostFrameCallback((_) async {
      if ((FFAppState().onboardingStarted == true) &&
          (FFAppState().onboardingComplete == false)) {
        context.goNamedAuth(
            OnboardingAnalyzingWidget.routeName, context.mounted);

        return;
      } else {
        if (!FFAppState().onboardingComplete) {
          GoRouter.of(context).prepareAuthEvent();
          await authManager.signOut();
          GoRouter.of(context).clearRedirectLocation();

          context.goNamedAuth(
            WelcomeWidget.routeName,
            context.mounted,
            extra: <String, dynamic>{
              '__transition_info__': TransitionInfo(
                hasTransition: true,
                transitionType: PageTransitionType.fade,
                duration: Duration(milliseconds: 0),
              ),
            },
          );

          return;
        }
      }

      await Future.wait([
        Future(() async {
          if (widget.tabIndex != null) {
            _model.tabIndex = widget.tabIndex!;
            safeSetState(() {});
            safeSetState(() {
              _model.tabBarController!.animateTo(
                _model.tabIndex,
                duration: Duration(milliseconds: 300),
                curve: Curves.ease,
              );
            });

            return;
          } else {
            return;
          }
        }),
        Future(() async {
          _model.friends = await FriendsTable().queryRows(
            queryFn: (q) => q.eqOrNull(
              'user_id',
              currentUserUid,
            ),
          );
          _model.campaigns = await UserCampaignsTable().queryRows(
            queryFn: (q) => q.eqOrNull(
              'user_id',
              currentUserUid,
            ),
          );
        }),
        Future(() async {
          if (_model.scrollToCourseId != null &&
              _model.scrollToCourseId != '') {
            _model.scrollToCourseId = widget.scrollToCourseId;
            safeSetState(() {});
            return;
          } else {
            _model.scrollToCourseId = FFAppState().lastEngagedCourseId;
            safeSetState(() {});
            return;
          }
        }),
        Future(() async {
          if (FFAppState().exploreUcpIdsJson.isNotEmpty) {
            return;
          }

          _model.ucp = await UserCourseProgressTable().queryRows(
            queryFn: (q) => q.eqOrNull(
              'user_id',
              currentUserUid,
            ),
          );
          for (int loop1Index = 0;
              loop1Index < _model.ucp!.length;
              loop1Index++) {
            final currentLoop1Item = _model.ucp![loop1Index];
            FFAppState().addToExploreUcpIdsJson(<String, dynamic>{
              'course_id': currentLoop1Item.courseId,
              'lessons_completed': currentLoop1Item.lessonsCompleted,
              'total_lessons': currentLoop1Item.totalLessons,
            });
            safeSetState(() {});
          }
          return;
        }),
        Future(() async {
          await actions.initPushNavigationHandler(
            context,
          );
        }),
      ]);
    });

    if (!isWeb) {
      _keyboardVisibilitySubscription =
          KeyboardVisibilityController().onChange.listen((bool visible) {
        safeSetState(() {
          _isKeyboardVisible = visible;
        });
      });
    }

    _model.tabBarController = TabController(
      vsync: this,
      length: 9,
      initialIndex: min(
          valueOrDefault<int>(
            _model.tabIndex,
            0,
          ),
          8),
    )..addListener(() => safeSetState(() {}));

    _model.encountersSearchTextController ??= TextEditingController();
    _model.encountersSearchFocusNode ??= FocusNode();

    _model.searchTextController1 ??= TextEditingController();
    _model.searchFocusNode1 ??= FocusNode();

    _model.searchTextController2 ??= TextEditingController();
    _model.searchFocusNode2 ??= FocusNode();

    _model.searchTextController3 ??= TextEditingController();
    _model.searchFocusNode3 ??= FocusNode();
  }

  @override
  void dispose() {
    _model.dispose();

    if (!isWeb) {
      _keyboardVisibilitySubscription.cancel();
    }
    super.dispose();
  }

